import React, { Component } from 'react';
import { Modal, Button, FormGroup, Form } from 'react-bootstrap';
import axios from 'axios';
import moment from 'moment';
import { stringify } from 'qs';
import DatePicker from 'react-datepicker';
import Select from 'react-select';
import { toast } from 'react-toastify';
import { Formik } from 'formik';
import { camelCase, isEmpty } from 'lodash';

import { axiosError, resolveClientUrl } from '../../common-functions';
import getResource from '../../resourceHelper';
import { DateFormat, InputErrorCssClass } from '../../constants';

export default class Create extends Component {
    validateForm = values => {
        const errors = {};

        if (!values.employee) {
            errors.employee = getResource('EmployeeRequired');
        }

        if (!values.effectiveDate) {
            errors.effectiveDate = getResource('IssueDateRequired');
        }

        if (!values.description) {
            errors.description = getResource('ContentRequired');
        }

        return errors;
    }

    handleSubmit = (values, { setErrors }) => {
        axios({
            url: resolveClientUrl('discipline/create'),
            method: 'post',
            data: stringify({
                __RequestVerificationToken: document.getElementsByName('__RequestVerificationToken')[0].value,
                disciplineId: values.disciplineId,
                employeeId: values.employee.value,
                effectiveDate: values.effectiveDate.format('YYYY-MM-DD'),
                content: values.description
            }),
            headers: {
                'X-Requested-With': 'XMLHttpRequest',
                'Content-Type': 'application/x-www-form-urlencoded'
            }
        }).then(response => {
            const data = response.data;

            if (data.isSuccessful) {
                toast.success(getResource('CreatedSuccessfully'));

                this.props.onCreateSuccess();
            } else {
                if (data.errors) {
                    const errors = {};
                    data.errors.map(error => {
                        errors[camelCase(error.key)] = error.errorMessage;
                    });

                    setErrors(errors);
                } else {
                    toast.error(data.message);
                }
            }
        }).catch(axiosError);
    }

    renderForm = ({
        values,
        errors,
        touched,
        handleChange,
        handleSubmit,
        setFieldValue }) => {
        return (
            <Form className="discipline-form" id="create-form" inline onSubmit={handleSubmit}>
                <Modal.Body>
                    {
                        !isEmpty(errors) && !isEmpty(touched) &&
                        <ul className="list-message-error">
                            {touched.employee && errors.employee && <li>{errors.employee}</li>}
                            {touched.effectiveDate && errors.effectiveDate && <li>{errors.effectiveDate}</li>}
                            {touched.description && errors.description && <li>{errors.description}</li>}
                        </ul>
                    }
                    <div className="line-group">
                        <FormGroup>
                            <label className="control-label required-label">{getResource('Employee')}</label>
                            <div className="control-content">
                                <Select name="employee"
                                    className={`react-select-container ${touched.employee && errors.employee && InputErrorCssClass}`}
                                    classNamePrefix="react-select"
                                    isDisabled={values.disciplineId > 0} isClearable
                                    options={this.props.employeeOptions}
                                    value={values.employee}
                                    onChange={value => setFieldValue('employee', value)}
                                />
                            </div>
                        </FormGroup>
                        <FormGroup>
                            <label className="required-label control-label">{getResource('IssueDate')}</label>
                            <div className="control-content">
                                <DatePicker className={`form-control  ${touched.effectiveDate && errors.effectiveDate && InputErrorCssClass}`}
                                    dateFormat={DateFormat} selected={values.effectiveDate}
                                    onChange={value => setFieldValue('effectiveDate', value)}
                                    onChangeRaw={this.onChangeRaw}
                                    name="effectiveDate" autoComplete="off"
                                />
                            </div>
                        </FormGroup>
                        <FormGroup className="description-group">
                            <label className="required-label control-label">{getResource('Content')}</label>
                            <div className="control-content">
                                <textarea className={`form-control none-resize ${touched.description && errors.description && InputErrorCssClass}`}
                                    name="description" rows="10"
                                    onChange={handleChange}
                                    value={values.description}
                                />
                            </div>
                        </FormGroup>
                    </div>
                </Modal.Body>
                <Modal.Footer>
                    <Button className="btn btn-cancel" onClick={this.props.onClose}>{getResource('Cancel')}</Button>
                    <Button type="submit" className="btn btn-primary">{getResource('Submit')}</Button>
                </Modal.Footer>
            </Form>
        );
    }

    render() {
        const discipline = {
            employee: null,
            effectiveDate: moment(),
            description: ''
        };

        return (
            <Modal keyboard={false} backdrop="static"
                show={this.props.showModal}
                onHide={this.props.onClose}
                dialogClassName="custom-modal"
            >
                <Modal.Header closeButton>
                    <Modal.Title>{getResource('AddDiscipline')}</Modal.Title>
                </Modal.Header>
                <Formik initialValues={discipline}
                    validate={this.validateForm}
                    onSubmit={this.handleSubmit}
                    render={this.renderForm}
                />
            </Modal>
        );
    }
}